<?php use App\Core\Csrf; use App\Core\View; $modeNames=['unmastered'=>'未掌握错题','wrong'=>'全部历史错题','review'=>'待复习','favorite'=>'收藏题','due'=>'今日到期']; ?>
<div class="page-head"><div><h1><?= View::e($modeNames[$mode]??'复习') ?></h1><p><?php if($latest):?>本题复习结果 · 当前筛选 <?= (int)$total ?> 题<?php else:?><?= (int)$position ?> / <?= (int)$total ?><?php endif;?></p></div><a class="btn" href="/student/review-center">返回复习中心</a></div>
<?php if(!$question):?><article class="card empty">当前没有符合条件的题目。<div class="top-gap"><a class="btn btn-primary" href="/student">返回学习中心</a></div></article><?php else:$options=json_decode($question['options_json'],true)?:[];$correct=json_decode($question['correct_answers_json'],true)?:[];$return='/student/review?mode='.rawurlencode($mode).'&n='.$position;$latestAnswer=$latest?json_decode($latest['answer_json'],true)?:[]:[];?>
<article class="card study-question-card"><div class="toolbar spread"><div><span class="badge"><?= View::e(['single'=>'单选','multiple'=>'多选','judge'=>'判断','fill'=>'填空'][$question['question_type']]??$question['question_type']) ?></span><span class="muted"><?= View::e($question['chapter']??'未分类') ?> · 历史答错 <?= (int)$question['wrong_count'] ?> 次</span></div><div class="toolbar"><form method="post" action="/student/question/<?= $question['id'] ?>/favorite"><?= Csrf::field() ?><input type="hidden" name="return_to" value="<?= View::e($return) ?>"><button class="btn btn-sm <?= $question['favorite']?'btn-primary':'' ?>"><?= $question['favorite']?'★ 已收藏':'☆ 收藏' ?></button></form><form method="post" action="/student/question/<?= $question['id'] ?>/review-flag"><?= Csrf::field() ?><input type="hidden" name="return_to" value="<?= View::e($return) ?>"><button class="btn btn-sm <?= $question['needs_review']?'btn-warning':'' ?>"><?= $question['needs_review']?'△ 待复习':'○ 标记待复习' ?></button></form></div></div><h2><?= View::e($question['title']) ?></h2><div class="prompt study-prompt"><?= nl2br(View::e($question['prompt'])) ?></div>
<?php if($latest):?><section class="answer-panel <?= $latest['is_correct']?'answer-ok':'answer-bad' ?>"><div class="result-title"><?= $latest['is_correct']?'✓ 本次复习正确':'✕ 本次仍需复习' ?></div><p>正确答案：<strong><?php if($question['question_type']==='judge')echo ($correct[0]??'')==='T'?'对':'错';else echo View::e($correct?implode(' / ',$correct):'题库原文未提供标准答案');?></strong></p><?php if($question['explanation']):?><div class="answer-reference"><?= nl2br(View::e($question['explanation'])) ?></div><?php endif;?></section><div class="toolbar top-gap"><?php if(($nextPosition??0)>0):?><a class="btn btn-primary" href="/student/review?mode=<?= rawurlencode($mode) ?>&n=<?= (int)$nextPosition ?>">继续复习</a><?php else:?><a class="btn btn-primary" href="/student/review-center">本组复习完成</a><?php endif;?></div>
<?php else:?><form method="post" action="/student/review/<?= $question['id'] ?>/answer"><?= Csrf::field() ?><input type="hidden" name="mode" value="<?= View::e($mode) ?>"><input type="hidden" name="position" value="<?= (int)$position ?>">
<?php if($question['question_type']==='fill'):?><div class="field top-gap"><label>你的答案</label><input name="answer_text" autocomplete="off" required></div><details class="answer-reference top-gap"><summary>查看标准答案后自评</summary><p><?= View::e($correct?implode(' / ',$correct):'题库原文未提供标准答案') ?></p><?php if($question['explanation']):?><p><?= nl2br(View::e($question['explanation'])) ?></p><?php endif;?></details><div class="toolbar top-gap"><button class="btn btn-success" name="self_result" value="correct">我答对了</button><button class="btn btn-warning" name="self_result" value="review">需要复习</button></div>
<?php else:$input=($question['question_type']==='multiple'||count($correct)>1)?'checkbox':'radio';?><div class="options top-gap"><?php foreach($options as$letter=>$text):?><label class="option option-large"><input type="<?= $input ?>" name="answer[]" value="<?= View::e($letter) ?>"><strong><?= $question['question_type']==='judge'?View::e($text):View::e($letter).'.' ?></strong><?php if($question['question_type']!=='judge'):?><span><?= View::e($text) ?></span><?php endif;?></label><?php endforeach;?></div><button class="btn btn-primary top-gap">提交并查看答案</button><?php endif;?></form><?php endif;?></article>
<?php if(!$latest):?><div class="sticky-actions"><div><?php if($position>1):?><a class="btn" href="/student/review?mode=<?= rawurlencode($mode) ?>&n=<?= $position-1 ?>">← 上一题</a><?php endif;?></div><div><?php if($position<$total):?><a class="btn" href="/student/review?mode=<?= rawurlencode($mode) ?>&n=<?= $position+1 ?>">下一题 →</a><?php endif;?></div></div><?php endif;?>
<?php endif;?>
